  \centering
  \includegraphics[width=0.7\linewidth]{images/feature_discrepancy_ablation.pdf}
  \caption{Ablation study on diffusion strength. The plot depicts the average feature discrepancy (Euclidean distance) relative to the mean prototype embedding as a function of the diffusion strength.}
  \label{fig:ablation}
\end{figure}

\subsection{Adaptive Domain Mixing via Curriculum Learning}
Experiment 3 evaluates the effect of adaptive domain mixing on classifier convergence. In this experiment, training starts with a higher proportion of baseline synthetic images and progressively incorporates more diffusion-enhanced images over successive epochs. The mixing ratio at each epoch is defined as
\[
  r(\text{epoch}) = \frac{\text{epoch}}{\text{total epochs}},
\]
so that as training proceeds the emphasis gradually shifts toward the augmented data.

The adaptive mixing routine is detailed in Algorithm~\ref{alg:curriculum}.

\begin{algorithm}[H]
\caption{Adaptive Domain Mixing via Curriculum Learning}\label{alg:curriculum}
\begin{algorithmic}[1]
  \State Initialize total epochs \(T\) and set mixing ratio \(r \leftarrow 0\).
  \For{\(epoch = 1\) to \(T\)}
    \State Update ratio: \(r \leftarrow epoch/T\).
    \For{each paired batch \((B, D)\) from the baseline and diffusion datasets}
      \State Initialize an empty mixed batch \(M\).
      \For{each sample pair \((b, d)\) in \((B, D)\)}
        \If{\(\mathrm{random()} < r\)}
          \State Append \(d\) to \(M\).
        \Else
          \State Append \(b\) to \(M\).
        \EndIf
      \EndFor
      \State Use \(M\) for the forward and backward training steps.
    \EndFor
  \EndFor
\end{algorithmic}
\end{algorithm}

